func TestPrintStatusStyledAndLegacy(t *testing.T) {
	oldStyled, oldColor := styledOutput, colors.IsEnabled()
	t.Cleanup(func() {
		styledOutput = oldStyled
		if oldColor {
			colors.Enable()
		} else {
			colors.Disable()
		}

	})
	colors.Disable()
	var out bytes.Buffer
	styledOutput = true
	printStatus(&out, "✓", "config", "file written", "original\n")
	if got := out.String(); got != "✓ config     file written\n" {
		t.Fatalf("styled output = %q", got)
	}
	out.Reset()
	styledOutput = false
	printStatus(&out, "✓", "config", "file written", "original\n")
	if got := out.String(); got != "original\n" {
		t.Fatalf("legacy output = %q", got)
	}
}

